
#pragma once

#include <string>
#include <stdexcept>

struct MBOconfig {
    /** Number of birds (ODD)*/
    int n = 51;

    /** Neighbors generated by the leader*/
    int k = 3;

    /** leftover neighbors shared with the bird behind */
    int x = 1;

    /** Tours before the leader is rotated */
    int t = 10;

    /**  Limit on neighbor evaluations */
    int K = 10000;

    inline void validate() const;
};

void MBOconfig::validate() const {
    if (n < 1) 
        throw std::invalid_argument("MBO: n must be >= 1");

    if (k < 1) 
        throw std::invalid_argument("MBO: k must be >= 1");

    if (t < 1) 
        throw std::invalid_argument("MBO: m must be >= 1");

    if (K < 1)
        throw std::invalid_argument("MBO: K must be >= 1");

    if (x < 0 || x >= k) 
        throw std::invalid_argument("MBO: need 0 <= x < k");

    if (x > 0 && k < 2 * x + 1)
        throw std::invalid_argument("MBO: neeed k >= 2x+1. k=" + std::to_string(k) + ", x=" + std::to_string(x));
}
